// ============================================================
//  HORROR BETA 0.5 - BOSQUE  [version CIRCULO + ONLINE + SETS DE LLAVES]  (PS2 homebrew, PS2SDK + gsKit)
//
//  Controles (DualShock 2):
//    Stick izq  : moverse (empujalo al tope para CORRER, gasta estamina)
//    Stick der  : mirar (izq-der y arriba 80 / abajo 70 grados)
//    FLECHA DER.: menu de EMOJIS (flechas mueven, X envia, O cierra). Las demas flechas quedan libres.
//    X (cruz)   : saltar  (junto a un pozo: subir/bajar la escalera)
//    O (circulo): agacharse / levantarse
//    L1         : linterna ON/OFF       START : pausa
//    R2 (mantener 5 s): carga el DETECTOR (barra abajo a la izquierda); lleno, sube al centro y marca los METROS al monstruo ("---" = otro nivel)
//    CUADRADO   : junto al cartel del inicio, toma el MAPA
//    TRIANGULO  : abre / cierra el mapa (superficie + alcantarilla)
//    CUADRADO   : junto a una puerta: abrirla con su llave de color / poner el codigo del candado
//    R1 (mantener): ver tus llaves y los codigos que ya encontraste
//    L2 (mantener 1 s): luz ULTRAVIOLETA (la linterna se vuelve morada); otra vez para volver a la normal
//    2 JUGADORES: pantalla dividida (J1 arriba con el control 1, J2 abajo con el control 2)
//    SELECT     : invierte la luz si en tu emulador se ve al reves
//    SERVIDOR   : ONLINE > SERVIDOR: SI + IP DEL SERVIDOR -> salas por internet y relay (ver horror_server.py)
//    ONLINE     : menu principal > ONLINE (necesita compilar con -DUSE_NET y el adaptador de red de la PS2)
//                 CREAR PARTIDA abre una sala de espera (J1 / J2, boton COMENZAR); PARTIDAS PUBLICAS lista las salas de tu red
//
//  Objetivo: abre las puertas en orden y reune las 3 LLAVES FINALES (cabana, cueva y caseta de la antena);
//  con ellas se abre la PUERTA FINAL, escondida en la alcantarilla (cuarto del fondo, al sur). Algo te esta buscando...
//  Orden: llave ROJA (camino) -> casa del inicio (llave AZUL) y casita de piedra (papel CABANA)
//         llave AZUL -> establo (llave AMARILLA) y edificio NO (papel ANTENA)
//         llave AMARILLA -> edificio NE (llave VERDE) -> cueva (LLAVE FINAL)
//         codigo CABANA -> cabana (LLAVE FINAL)    codigo ANTENA -> caseta de la antena (LLAVE FINAL)
// ============================================================
#include <tamtypes.h>
#include <kernel.h>
#include <sifrpc.h>
#include <loadfile.h>
#include <iopheap.h>
#ifndef NET_PC_TEST
#include <sbv_patches.h>
#endif
#include <libpad.h>
#include <gsKit.h>
#include <dmaKit.h>
#include <math.h>
#include <stdio.h>
#include <string.h>
#if !(defined(_EE) || defined(__mips__) || defined(__mips))
#include <time.h>         // solo para compilar pruebas en PC (en PS2 el FPS usa el contador del CPU)
#endif
#if defined(USE_NET) || defined(NET_PC_TEST)
#define HAVE_NET 1
#endif
#ifdef USE_NET                      // PS2: modulos DEV9 + NETMAN + SMAP (IOP) y pila TCP/IP (ps2ip)
#include <netman.h>
#include <ps2ip.h>
extern unsigned char DEV9_irx[];   extern unsigned int size_DEV9_irx;
extern unsigned char NETMAN_irx[]; extern unsigned int size_NETMAN_irx;
extern unsigned char SMAP_irx[];   extern unsigned int size_SMAP_irx;
#define NS_socket(a, b, c)            lwip_socket(a, b, c)
#define NS_bind(s_, a, l)             lwip_bind(s_, a, l)
#define NS_sendto(s_, b, n, f, a, l)  lwip_sendto(s_, b, n, f, a, l)
#define NS_recvfrom(s_, b, n, f, a, l) lwip_recvfrom(s_, b, n, f, a, l)
#define NS_close(s_)                  lwip_close(s_)
#define NS_setsockopt(s_, l, o, v, n) lwip_setsockopt(s_, l, o, v, n)
#ifndef MSG_DONTWAIT
#define MSG_DONTWAIT 0x08
#endif
#endif
#ifdef NET_PC_TEST                  // solo pruebas en PC (dos copias del juego por localhost)
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdlib.h>
#define NS_socket(a, b, c)            socket(a, b, c)
#define NS_bind(s_, a, l)             bind(s_, a, l)
#define NS_sendto(s_, b, n, f, a, l)  sendto(s_, b, n, f, a, l)
#define NS_recvfrom(s_, b, n, f, a, l) recvfrom(s_, b, n, f, a, l)
#define NS_close(s_)                  close(s_)
#define NS_setsockopt(s_, l, o, v, n) setsockopt(s_, l, o, v, n)
#endif
#ifdef USE_AUDIO
#include <audsrv.h>
extern unsigned char audsrv_irx[];
extern unsigned int  size_audsrv_irx;
#ifdef USE_FREESD
extern unsigned char freesd_irx[];
extern unsigned int  size_freesd_irx;
#endif
#endif
// ---------------- Vista (pantalla dividida) ----------------
// Todo el dibujo pasa por estas macros: suman el origen de la vista (VX,VY) a cada
// primitiva, asi el mismo codigo dibuja a pantalla completa o en media pantalla.
static float VX, VY;            // origen de la vista actual (en pantalla)
static float SW, SH;            // tamano de la pantalla completa
static int   view_part;         // 1: dibujando en media pantalla (con scissor)
static void  clear_view(u64 col);
#define gsKit_prim_sprite(g, x1, y1, x2, y2, z, c) \
    gsKit_prim_sprite(g, (x1) + VX, (y1) + VY, (x2) + VX, (y2) + VY, z, c)
#define gsKit_prim_triangle_gouraud_3d(g, x1, y1, z1, x2, y2, z2, x3, y3, z3, c1, c2, c3) \
    gsKit_prim_triangle_gouraud_3d(g, (x1) + VX, (y1) + VY, z1, (x2) + VX, (y2) + VY, z2, (x3) + VX, (y3) + VY, z3, c1, c2, c3)
#define gsKit_clear(g, c) clear_view(c)
#define MY_SCISSOR(x0, x1, y0, y1) (((u64)(x0)) | ((u64)(x1) << 16) | ((u64)(y0) << 32) | ((u64)(y1) << 48))

