static const char font_order[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789:<>-./";

static void draw_text(float x, float y, const char *str, int sc, u64 col)
{
    for (; *str; str++, x += 6.0f * sc) {
        const char *p = strchr(font_order, *str);
        if (!p || *str == '\0') continue;
        const unsigned char *g = font5x7[p - font_order];
        for (int r = 0; r < 7; r++) {
            int c = 0;
            while (c < 5) {
                if (!(g[r] & (0x10 >> c))) { c++; continue; }
                int c0 = c;
                while (c < 5 && (g[r] & (0x10 >> c))) c++;
                gsKit_prim_sprite(gsGlobal, x + c0 * sc, y + r * sc, x + c * sc, y + (r + 1) * sc, 16777200, col);
            }
        }
    }
}
static float text_w(const char *str, int sc) { return (float)strlen(str) * 6.0f * sc - sc; }
static void draw_text_c(float y, const char *str, int sc, u64 col) { draw_text((W - text_w(str, sc)) * 0.5f, y, str, sc, col); }

// ---------------- Contador de FPS en tiempo real (arriba a la derecha) ----------------
#if defined(_EE) || defined(__mips__) || defined(__mips)
static inline unsigned int cpu_count(void) { unsigned int v; __asm__ volatile("mfc0 %0, $9" : "=r"(v)); return v; }
#define FPS_TICKS_PER_SEC 294912000.0f           // el contador COUNT del EE avanza a 294.912 MHz
#else
static inline unsigned int cpu_count(void)        // PC (solo pruebas): microsegundos de reloj real
{ struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts); return (unsigned int)(ts.tv_sec * 1000000u + ts.tv_nsec / 1000u); }
#define FPS_TICKS_PER_SEC 1000000.0f
#endif
static float fps_val;
static void fps_update(void)                      // llamar una vez por cuadro
{
    static unsigned int last = 0, acc = 0;
    static int n = 0, started = 0;
    unsigned int now = cpu_count();
    if (!started) { last = now; started = 1; return; }
    acc += now - last; last = now; n++;           // resta sin signo: tolera el desbordamiento del contador
    if ((float)acc >= FPS_TICKS_PER_SEC * 0.5f) { // se refresca cada medio segundo
        fps_val = (float)n * FPS_TICKS_PER_SEC / (float)acc;
        acc = 0; n = 0;
    }
}
static void fps_draw(void)
{
    char buf[16];
    int v = (int)(fps_val + 0.5f);
    snprintf(buf, sizeof(buf), "FPS %d", v);
    u64 col = v >= 45 ? GS_SETREG_RGBAQ(90, 210, 110, 0x80, 0)
            : (v >= 28 ? GS_SETREG_RGBAQ(230, 190, 60, 0x80, 0) : GS_SETREG_RGBAQ(220, 60, 40, 0x80, 0));
    draw_text(W - text_w(buf, 2) - 10.0f, 8.0f, buf, 2, col);
}

// Dibuja todo el juego (usado tambien como fondo de la pausa)
// ---------------- Llave 3D tirada en el piso ----------------
// Una llave de verdad, acostada en el suelo (sin flotar ni girar): argolla octagonal con hueco, cuello,
// caña larga y dos dientes. Todo son cajas rotadas, asi que usa la misma luz que el resto del nivel.
static void key_part(float cx, float cz, float a, float lx, float lz, float da,
                     float hx, float hz, float y0, float y1, const float *col, float em)
{
    float s = sinf(a), c = cosf(a);
    box_rot(cx + lx * c + lz * s, cz - lx * s + lz * c, a + da, 0.0f, 0.0f, hx, hz, y0, y1, col, em);
}

static void draw_key(float x, float z, float fy, float a)
{
    static const float gold[3] = { 170.f, 226.f, 245.f };      // llave final: plata azulada (la amarilla es la de la puerta del noreste)
    static const float dark[3] = { 120.f, 168.f, 196.f };
    const float em = 0.32f;
    const float y0 = fy + 0.015f, y1 = fy + 0.095f;
    const float R = 0.15f;                                    // radio medio de la argolla
    for (int k = 0; k < 8; k++) {                             // argolla: 8 barras formando un octagono con hueco
        float ang = k * (PI_F / 4.0f);
        key_part(x, z, a, -0.42f + R * cosf(ang), R * sinf(ang), -(ang + PI_F * 0.5f),
                 0.068f, 0.040f, y0, y1, gold, em);
    }
    key_part(x, z, a, -0.22f, 0.0f, 0.0f, 0.030f, 0.075f, y0, y1 + 0.012f, dark, em);   // cuello
    key_part(x, z, a,  0.18f, 0.0f, 0.0f, 0.400f, 0.032f, y0, y1, gold, em);            // caña
    key_part(x, z, a,  0.50f, 0.080f, 0.0f, 0.050f, 0.050f, y0, y1, dark, em);          // dientes
    key_part(x, z, a,  0.37f, 0.070f, 0.0f, 0.040f, 0.040f, y0, y1, dark, em);
}

// ---------------- Cartel del mapa (al inicio) ----------------
static void draw_map_board(float t)
{
    if (cur_layer != 0 && !climbing) return;
    if (!in_view(MAPB_X, MAPB_Z, 2.0f, (gfx_pd[gfx] * rd_k))) return;
    static const float wood[3]  = {  96.f,  66.f,  40.f };
    static const float board[3] = { 128.f,  92.f,  58.f };
    static const float paper[3] = { 222.f, 204.f, 158.f };
    static const float ink[3]   = {  70.f,  52.f,  34.f };
    static const float mark[3]  = { 200.f,  50.f,  40.f };
    float pe = has_map ? 0.20f : 0.30f + 0.10f * sinf(t * 3.0f);    // el papel llama la atencion hasta que lo tomas
    box_rot(MAPB_X - 1.0f, MAPB_Z, 0.0f, 0.0f, 0.0f, 0.07f, 0.07f, 0.0f, 2.05f, wood, 0.0f);     // postes
    box_rot(MAPB_X + 1.0f, MAPB_Z, 0.0f, 0.0f, 0.0f, 0.07f, 0.07f, 0.0f, 2.05f, wood, 0.0f);
    box_rot(MAPB_X, MAPB_Z, 0.0f, 0.0f, 0.0f, MAPB_HX, 0.05f, 0.95f, 2.05f, board, 0.0f);          // tablero
    box_rot(MAPB_X, MAPB_Z, 0.0f, 0.0f, 0.0f, MAPB_HX + 0.12f, 0.20f, 2.05f, 2.12f, wood, 0.0f);   // techito
    box_rot(MAPB_X, MAPB_Z, 0.0f, 0.0f, 0.062f, 0.95f, 0.010f, 1.10f, 1.95f, paper, pe);           // el mapa (cara hacia +z, donde apareces)
    box_rot(MAPB_X, MAPB_Z, 0.0f, 0.0f, 0.0775f, 0.03f, 0.004f, 1.18f, 1.87f, ink, pe * 0.7f);     // trazos de tinta
    box_rot(MAPB_X, MAPB_Z, 0.0f, -0.35f, 0.0775f, 0.50f, 0.004f, 1.50f, 1.54f, ink, pe * 0.7f);
    box_rot(MAPB_X, MAPB_Z, 0.0f, 0.40f, 0.0775f, 0.05f, 0.004f, 1.20f, 1.30f, mark, 0.4f);        // marca roja
}

// Avisos en pantalla: tomar el mapa / como abrirlo
